def ids(kind, numbers):
    return [f"NET-{kind}{i:02d}" for i in numbers]


def source(n, title, authors, year, url, typ, access, locator, limit, lineage):
    return dict(id=f"NET-S{n:02d}", title=title, authors=authors, year=year,
                url=url, source_type=typ, access=access, locator=locator,
                scope_limit=limit, accessed=DATE, evidence_lineage=lineage)


