def support(n, locator, supports):
    return dict(source_id=f"NET-S{n:02d}", locator=locator, supports=supports)


def test(chain, rival, observation, found, ambiguity, timing="emerged during research", status="underdetermined"):
    return dict(status=status, mechanism_chain=chain, strongest_rival=rival,
                discriminating_observation=observation, evidence_sought_found=found,
                remaining_ambiguity=ambiguity, hypothesis_timing=timing)


def claim(n, cases, statement, etype, confidence, causal, supports, counter, limits, testing=None):
    return dict(id=f"NET-K{n:02d}", case_ids=ids("C", cases), statement=statement,
                evidence_type=etype, confidence=confidence, causal_status=causal,
                sources=supports, counterevidence=counter, inference_limits=limits,
                test=testing or dict(status="descriptive-only", reason="Bounded statement about records, material observations or reported counts; no independent causal effect asserted."))


