def case(n, title, region, period, domain, outcome, summary, stages, mechanisms,
         counter, claim_numbers, source_numbers, episode, actors, labour):
    return dict(id=f"NET-C{n:02d}", title=title, region=region, period=period,
                domain=domain, outcome=outcome, summary=summary, stages=stages,
                mechanisms=mechanisms, counterevidence=counter,
                claim_ids=ids("K", claim_numbers), source_ids=ids("S", source_numbers),
                episode=episode, actors=actors, labour=labour)


