claim_by_id = {c["id"]: c for c in claims}


def edge(n, source_node, target_node, relation, case_number, claim_numbers,
         basis, stage, configuration, qualification, alternatives, dispute,
         confidence="medium"):
    cids = ids("K", claim_numbers)
    source_ids = sorted({s["source_id"] for cid in cids for s in claim_by_id[cid]["sources"]})
    return dict(id=f"NET-E{n:02d}", **{"from": f"NET-T{source_node:02d}", "to": f"NET-T{target_node:02d}"},
                relation=relation, case_ids=ids("C", [case_number]), claim_ids=cids,
                source_ids=source_ids, confidence=confidence, qualification=qualification,
                basis=basis, scope=dict(case_id=f"NET-C{case_number:02d}", stage=stage,
                                       configuration=configuration),
                alternatives=alternatives, joint_inputs=[], necessity_rationale="No necessity claim",
                dispute=dispute)


