def validate():
    """Check local structure/references; this does not certify historical truth."""
    kinds = {"cases": cases, "sources": sources, "claims": claims,
             "nodes": nodes, "edges": edges, "comparisons": comparisons}
    index = {kind: {row["id"]: row for row in rows} for kind, rows in kinds.items()}
    all_ids = [row["id"] for rows in kinds.values() for row in rows]
    assert len(set(all_ids)) == len(all_ids), "duplicate IDs"
    assert len(cases) == 6 and len(sources) == 15 and len(claims) == 24
    for kind, rows in kinds.items():
        for row in rows:
            for field, target in [("case_ids", "cases"), ("claim_ids", "claims"), ("source_ids", "sources")]:
                assert set(row.get(field, [])) <= index[target].keys(), (row["id"], field)
    for c in cases:
        for field, keys in {
            "episode": ["technology_configuration", "task", "population", "interval", "contemporary_alternatives", "adoption_measure", "observation_limits"],
            "actors": ["chooser", "payer", "operator_maintainer", "affected_nonchooser", "ability_to_refuse"],
            "labour": ["tasks", "entry_barriers", "bargaining_ownership", "transition", "distribution", "evidence_limit"],
        }.items():
            assert all(c[field].get(key) for key in keys), (c["id"], field)
        assert {s["source_id"] for cid in c["claim_ids"] for s in index["claims"][cid]["sources"]} <= set(c["source_ids"])
    for c in claims:
        assert all(s["source_id"] in index["sources"] and s["locator"] and s["supports"] for s in c["sources"])
        if c["causal_status"] == "descriptive":
            assert c["test"]["status"] == "descriptive-only" and c["test"]["reason"]
        else:
            assert c["test"]["status"] in {"evaluated", "underdetermined", "proposed"}
            assert all(c["test"].get(key) for key in ["mechanism_chain", "strongest_rival", "discriminating_observation", "evidence_sought_found", "remaining_ambiguity", "hypothesis_timing"])
    for e in edges:
        assert e["from"] in index["nodes"] and e["to"] in index["nodes"]
        assert e["scope"]["case_id"] in e["case_ids"]
        assert e["basis"] in {"technical-possibility", "observed-contribution", "documented-transmission", "inferred-transmission", "bounded-necessity", "hypothesis"}
        assert e["relation"] != "depends-on" or e["basis"] == "bounded-necessity"
        assert e["necessity_rationale"] == "No necessity claim"
        assert all(e.get(key) for key in ["qualification", "alternatives", "dispute"])
        assert set(e["source_ids"]) == {s["source_id"] for cid in e["claim_ids"] for s in index["claims"][cid]["sources"]}
        assert e["scope"]["case_id"] in index["nodes"][e["from"]]["case_ids"]
        assert e["scope"]["case_id"] in index["nodes"][e["to"]]["case_ids"]
    assert all(s["evidence_lineage"] and s["locator"] and s["scope_limit"] for s in sources)
    return {kind: len(rows) for kind, rows in kinds.items()}


if __name__ == "__main__":
    counts = validate()
    outputs = {"cases": cases, "sources": sources, "claims": claims,
               "graph": {"nodes": nodes, "edges": edges}, "comparisons": comparisons}
    for name, value in outputs.items():
        (ROOT / f"{name}.json").write_text(json.dumps(value, ensure_ascii=False, indent=2) + "\n")
    print(json.dumps({"validation": "passed", "counts": counts, "limit": "Structural/reference checks, not independent historical validation."}))

